<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';use App\Core\Csrf;use App\Core\Database;$pdo=Database::connection();$mode=($_GET['mode']??$_POST['mode']??'new')==='update'?'update':'new';$error='';$success='';$matches=[];$q=trim((string)($_GET['q']??''));
if($mode==='update'&&$q!==''){$n=mb_strtolower(trim(preg_replace('/[^\pL\pN]+/u',' ',$q)??$q));$s=$pdo->prepare("SELECT id,bdc_id,exact_name,country,current_division,dance_role,photo_url FROM bdc_competitors WHERE exact_name LIKE :q OR normalised_name LIKE :n OR bdc_id=:id OR instagram=:ig ORDER BY exact_name LIMIT 20");$s->execute(['q'=>'%'.$q.'%','n'=>'%'.$n.'%','id'=>$q,'ig'=>ltrim($q,'@')]);$matches=$s->fetchAll();}
$bachataDivisions=['novice','intermediate','advanced','bachata_rising','bachata_open','bachata_invitational','semi_pro','pro','all_star'];$salsaDivisions=['novice','intermediate','advanced','salsa_rising','salsa_open'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$error='Invalid security token. Please refresh and try again.';else{$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$cid=(int)($_POST['competitor_id']??0);$competitionType=(string)($_POST['competition_type']??'jack_jill');$danceStyle=(string)($_POST['dance_style']??'bachata');if(!in_array($competitionType,['jack_jill','dance_cup'],true))$competitionType='jack_jill';if(!in_array($danceStyle,['bachata','salsa'],true))$danceStyle='bachata';$division=(string)($_POST['current_division']??'unknown');$allowed=$danceStyle==='salsa'?$salsaDivisions:$bachataDivisions;if($competitionType==='jack_jill'&&$division!=='unknown'&&!in_array($division,$allowed,true))$error='Invalid division for '.ucfirst($danceStyle).'.';if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Please enter a valid email or leave it blank.';elseif($mode==='update'&&$cid<1)$error='Please select your existing BDC profile.';else{$photo=null;$cropped=(string)($_POST['photo_cropped']??'');if($cropped!==''&&preg_match('#^data:image/jpeg;base64,([A-Za-z0-9+/=]+)$#',$cropped,$match)){$bytes=base64_decode($match[1],true);$mime=$bytes===false?'':(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes);if($bytes===false||strlen($bytes)>4*1024*1024||$mime!=='image/jpeg')$error='Adjusted photo could not be processed. Please choose the photo again.';else{$fn='request-'.bin2hex(random_bytes(8)).'.jpg';$dest=dirname(__DIR__).'/uploads/competitors/'.$fn;if(file_put_contents($dest,$bytes)===false)$error='Photo upload failed.';else$photo=url('uploads/competitors/'.$fn);}}elseif(!empty($_FILES['photo']['tmp_name'])){$f=$_FILES['photo'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allow=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allow[$mime])||$f['size']>5*1024*1024)$error='Photo must be JPG, PNG or WebP and under 5 MB.';else{$fn='request-'.bin2hex(random_bytes(8)).'.'.$allow[$mime];$dest=dirname(__DIR__).'/uploads/competitors/'.$fn;if(!move_uploaded_file($f['tmp_name'],$dest))$error='Photo upload failed.';else$photo=url('uploads/competitors/'.$fn);}}if($error===''){$type=$mode==='update'?'profile_update':'new_registration';$role=$competitionType==='jack_jill'?($_POST['dance_role']??'unknown'):'unknown';$division=$competitionType==='jack_jill'?$division:'unknown';$payload=json_encode(['submitted_ip'=>$_SERVER['REMOTE_ADDR']??null,'competition_type'=>$competitionType,'dance_style'=>$competitionType==='jack_jill'?$danceStyle:null],JSON_UNESCAPED_UNICODE);$s=$pdo->prepare("INSERT INTO bdc_profile_requests(request_type,competitor_id,full_name,email,phone,instagram,country,dance_role,current_division,photo_url,notes,payload_json,status) VALUES(:t,:cid,:n,:e,:p,:ig,:c,:r,:d,:photo,:notes,:payload,'pending')");$s->execute(['t'=>$type,'cid'=>$cid?:null,'n'=>$name,'e'=>$email,'p'=>trim((string)($_POST['phone']??''))?:null,'ig'=>ltrim(trim((string)($_POST['instagram']??'')),'@')?:null,'c'=>trim((string)($_POST['country']??''))?:null,'r'=>$role,'d'=>$division,'photo'=>$photo,'notes'=>trim((string)($_POST['notes']??''))?:null,'payload'=>$payload]);$success=$mode==='update'?'Your profile update request was submitted for admin approval.':'Your registration was submitted for admin approval.';}}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Competitor Registration</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>.photo-editor{display:none;margin-top:12px;padding:14px;border:1px solid #dee2e6;border-radius:10px;background:#f8f9fa}.photo-editor.is-open{display:block}.crop-stage{position:relative;width:240px;height:240px;max-width:100%;overflow:hidden;border-radius:50%;background:#dfe3e7;touch-action:none;cursor:grab}.crop-stage:active{cursor:grabbing}.crop-stage img{position:absolute;max-width:none;user-select:none;pointer-events:none}.crop-ring{position:absolute;inset:0;border:3px solid #fff;border-radius:50%;box-shadow:0 0 0 1px rgba(0,0,0,.18);pointer-events:none}.crop-controls{flex:1;min-width:210px}</style></head><body class="bg-light"><main class="container py-5" style="max-width:900px"><h1 class="mb-2">BDC Competitor Portal</h1><div class="btn-group mb-4"><a class="btn <?=$mode==='new'?'btn-dark':'btn-outline-dark'?>" href="?mode=new">New competitor</a><a class="btn <?=$mode==='update'?'btn-dark':'btn-outline-dark'?>" href="?mode=update">Update existing profile</a></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($mode==='update'):?><div class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5">Find your existing BDC ID</h2><form class="row g-2"><input type="hidden" name="mode" value="update"><div class="col-md-9"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search exact name, BDC ID or Instagram"></div><div class="col-md-3 d-grid"><button class="btn btn-outline-dark">Search</button></div></form></div></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card border-0 shadow-sm"><div class="card-body p-4"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="mode" value="<?=e($mode)?>"><?php if($mode==='update'):?><label class="form-label fw-semibold">Select your BDC profile</label><div class="row g-2 mb-3"><?php foreach($matches as $m):?><div class="col-md-6"><label class="border rounded p-3 d-flex gap-3 align-items-center w-100 bg-white"><input class="form-check-input" type="radio" name="competitor_id" value="<?=$m['id']?>" required><span><strong><?=e($m['exact_name'])?></strong><br><small><?=e($m['bdc_id'])?> · <?=e((string)$m['country'])?></small></span></label></div><?php endforeach;?></div><?php endif;?><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="full_name" placeholder="Optional"></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" placeholder="Optional"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone"></div><div class="col-md-6"><label class="form-label">Instagram</label><input class="form-control" name="instagram"></div><div class="col-md-6"><label class="form-label">Country</label><input class="form-control" name="country"></div><div class="col-md-6"><label class="form-label">Profile photo</label><input class="form-control" id="profilePhoto" type="file" name="photo" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="photo_cropped" id="photoCropped"><div class="photo-editor" id="photoEditor"><div class="d-flex flex-wrap gap-3 align-items-center"><div class="crop-stage" id="cropStage"><img id="cropImage" alt="Profile photo preview"><span class="crop-ring"></span></div><div class="crop-controls"><strong>Adjust photo</strong><input class="form-range" id="photoZoom" type="range" min="1" max="3" step="0.01" value="1" aria-label="Photo zoom"><button class="btn btn-outline-secondary btn-sm" type="button" id="photoReset">Reset</button></div></div></div></div><div class="col-12"><hr><h2 class="h5">Competition Profile</h2></div><div class="col-md-6"><label class="form-label fw-semibold">Competition Type</label><select id="competitionType" class="form-select" name="competition_type"><option value="jack_jill">Jack & Jill</option><option value="dance_cup">BDC Dance Cup</option></select></div><div class="col-md-6" id="danceStyleWrap"><label class="form-label fw-semibold">Dance Style</label><select class="form-select" name="dance_style" id="danceStyle"><option value="bachata">Bachata</option><option value="salsa">Salsa</option></select></div><div id="jackJillFields" class="col-12"><div class="row g-3"><div class="col-md-6"><label class="form-label">Role</label><select class="form-select" name="dance_role"><option value="unknown">Select</option><option value="leader">Lead</option><option value="follower">Follow</option><option value="both">Both</option></select></div><div class="col-md-6"><label class="form-label">Current division</label><select class="form-select" name="current_division" id="currentDivision"><option value="unknown">Select</option><optgroup label="BDC Divisions"><option value="novice">Novice</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="semi_pro" data-dance="bachata">Semi Pro</option><option value="pro" data-dance="bachata">Pro</option><option value="all_star" data-dance="bachata">Bachata All Star</option></optgroup><optgroup label="Special Categories"><option value="bachata_rising" data-dance="bachata">Bachata Rising</option><option value="bachata_open" data-dance="bachata">Bachata Open</option><option value="bachata_invitational" data-dance="bachata">Bachata Invitational</option><option value="salsa_rising" data-dance="salsa">Salsa Rising</option><option value="salsa_open" data-dance="salsa">Salsa Open</option></optgroup></select><div class="d-none" id="salsaDivisionNote"></div></div></div></div><div id="danceCupNote" class="col-12 d-none"></div><div class="col-12"><label class="form-label">Notes for admin</label><textarea class="form-control" name="notes" rows="3"></textarea></div></div><div class="mt-4"><button class="btn btn-dark btn-lg"><?=$mode==='update'?'Submit update request':'Submit registration'?></button></div></div></form></main><script>const type=document.getElementById('competitionType'),danceWrap=document.getElementById('danceStyleWrap'),dance=document.getElementById('danceStyle'),jj=document.getElementById('jackJillFields'),cup=document.getElementById('danceCupNote'),division=document.getElementById('currentDivision'),salsaNote=document.getElementById('salsaDivisionNote');function syncDivision(){[...division.options].forEach(o=>{const only=o.dataset.dance;o.hidden=!!only&&only!==dance.value;o.disabled=!!only&&only!==dance.value});const allowed=dance.value==='salsa'?['unknown','novice','intermediate','advanced','salsa_rising','salsa_open']:['unknown','novice','intermediate','advanced','bachata_rising','bachata_open','bachata_invitational','semi_pro','pro','all_star'];if(!allowed.includes(division.value))division.value='unknown';salsaNote.classList.toggle('d-none',dance.value!=='salsa')}function syncCompetition(){const isCup=type.value==='dance_cup';danceWrap.classList.toggle('d-none',isCup);jj.classList.toggle('d-none',isCup);cup.classList.toggle('d-none',!isCup);syncDivision()}type.addEventListener('change',syncCompetition);dance.addEventListener('change',syncDivision);syncCompetition();const photoInput=document.getElementById('profilePhoto'),photoEditor=document.getElementById('photoEditor'),cropStage=document.getElementById('cropStage'),cropImage=document.getElementById('cropImage'),photoZoom=document.getElementById('photoZoom'),photoReset=document.getElementById('photoReset'),photoCropped=document.getElementById('photoCropped');let cropScale=1,cropX=0,cropY=0,dragging=false,lastX=0,lastY=0;function cropMetrics(){const z=Number(photoZoom.value),w=cropImage.naturalWidth*cropScale*z,h=cropImage.naturalHeight*cropScale*z,maxX=Math.max(0,(w-240)/2),maxY=Math.max(0,(h-240)/2);cropX=Math.max(-maxX,Math.min(maxX,cropX));cropY=Math.max(-maxY,Math.min(maxY,cropY));return{w,h,x:(240-w)/2+cropX,y:(240-h)/2+cropY}}function drawCrop(){if(!cropImage.naturalWidth)return;const m=cropMetrics();Object.assign(cropImage.style,{width:m.w+'px',height:m.h+'px',left:m.x+'px',top:m.y+'px'});const canvas=document.createElement('canvas');canvas.width=canvas.height=600;const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,600,600);c.drawImage(cropImage,m.x*2.5,m.y*2.5,m.w*2.5,m.h*2.5);photoCropped.value=canvas.toDataURL('image/jpeg',.9)}function resetCrop(){if(!cropImage.naturalWidth)return;cropScale=Math.max(240/cropImage.naturalWidth,240/cropImage.naturalHeight);cropX=cropY=0;photoZoom.value='1';drawCrop()}photoInput.addEventListener('change',()=>{const file=photoInput.files[0];if(!file){photoEditor.classList.remove('is-open');photoCropped.value='';return}if(file.size>5*1024*1024){photoInput.setCustomValidity('Photo must be under 5 MB.');photoInput.reportValidity();return}photoInput.setCustomValidity('');const reader=new FileReader();reader.onload=()=>{cropImage.onload=()=>{photoEditor.classList.add('is-open');resetCrop()};cropImage.src=reader.result};reader.readAsDataURL(file)});photoZoom.addEventListener('input',drawCrop);photoReset.addEventListener('click',resetCrop);cropStage.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;cropStage.setPointerCapture(e.pointerId)});cropStage.addEventListener('pointermove',e=>{if(!dragging)return;cropX+=e.clientX-lastX;cropY+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;drawCrop()});cropStage.addEventListener('pointerup',()=>{dragging=false;drawCrop()});cropStage.addEventListener('pointercancel',()=>dragging=false);document.querySelector('form[enctype="multipart/form-data"]').addEventListener('submit',()=>{if(cropImage.naturalWidth)drawCrop()});</script></body></html>
